CREATE TABLE compensation_proposal(org_id TEXT NOT NULL,id TEXT NOT NULL,employee_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('initial','adjustment','correction')),status TEXT NOT NULL CHECK(status IN('draft','submitted','approved','rejected','withdrawn')),author_subject_id TEXT NOT NULL,revision_id TEXT NOT NULL,payload_id TEXT NOT NULL,effective_date DATE NOT NULL,before_term_id TEXT,revision BIGINT NOT NULL CHECK(revision>0),basis_revision BIGINT NOT NULL CHECK(basis_revision>=0),recorded_at TIMESTAMPTZ NOT NULL,approval_id TEXT,PRIMARY KEY(org_id,id),UNIQUE(org_id,id,employee_id),UNIQUE(org_id,id,employee_id,author_subject_id),CHECK((status='approved' AND approval_id IS NOT NULL) OR (status<>'approved' AND approval_id IS NULL)),CHECK((kind='initial' AND before_term_id IS NULL) OR (kind='adjustment' AND before_term_id IS NOT NULL) OR (kind='correction' AND before_term_id IS NULL)));
