CREATE TABLE compensation_approval(org_id TEXT NOT NULL,id TEXT NOT NULL,employee_id TEXT NOT NULL,proposal_id TEXT NOT NULL,proposal_revision_id TEXT NOT NULL,approver_subject_id TEXT NOT NULL,author_subject_id TEXT NOT NULL,payload_id TEXT NOT NULL,proposal_revision BIGINT NOT NULL CHECK(proposal_revision>0),basis_revision BIGINT NOT NULL CHECK(basis_revision>=0),comp_revision BIGINT NOT NULL CHECK(comp_revision=basis_revision+1),recorded_at TIMESTAMPTZ NOT NULL,submitted_status TEXT NOT NULL DEFAULT 'submitted' CHECK(submitted_status='submitted'),PRIMARY KEY(org_id,id),UNIQUE(org_id,id,employee_id),UNIQUE(org_id,id,employee_id,proposal_id),UNIQUE(org_id,id,employee_id,proposal_id,proposal_revision_id,basis_revision),UNIQUE(org_id,proposal_revision_id),UNIQUE(org_id,employee_id,comp_revision),CHECK(approver_subject_id<>author_subject_id));
CREATE TABLE compensation_event(org_id TEXT NOT NULL,id TEXT NOT NULL,employee_id TEXT NOT NULL,approval_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('initial','adjustment','correction_replacement','correction_reversal')),effective_date DATE NOT NULL,member_key TEXT NOT NULL DEFAULT '',before_term_id TEXT,after_term_id TEXT,corrects_event_id TEXT,sequence BIGINT NOT NULL CHECK(sequence>0),correction_group_id TEXT,created_term_id TEXT GENERATED ALWAYS AS (CASE WHEN kind='correction_reversal' THEN NULL ELSE after_term_id END) STORED,PRIMARY KEY(org_id,id),UNIQUE(org_id,id,employee_id),UNIQUE(org_id,id,employee_id,approval_id),UNIQUE(org_id,id,employee_id,approval_id,effective_date),UNIQUE(org_id,id,employee_id,after_term_id),UNIQUE(org_id,id,employee_id,created_term_id),UNIQUE(org_id,employee_id,sequence),UNIQUE(org_id,approval_id,member_key),UNIQUE(org_id,corrects_event_id),CHECK(corrects_event_id IS NULL OR corrects_event_id<>id),CHECK(before_term_id IS NULL OR after_term_id IS NULL OR before_term_id<>after_term_id),CHECK((kind='initial' AND before_term_id IS NULL AND after_term_id IS NOT NULL AND corrects_event_id IS NULL AND member_key='' AND correction_group_id IS NULL) OR (kind='adjustment' AND before_term_id IS NOT NULL AND after_term_id IS NOT NULL AND corrects_event_id IS NULL AND member_key='' AND correction_group_id IS NULL) OR (kind='correction_replacement' AND after_term_id IS NOT NULL AND corrects_event_id IS NOT NULL AND member_key ~ '^[a-z0-9_]{1,32}$' AND correction_group_id IS NOT NULL AND correction_group_id=approval_id) OR (kind='correction_reversal' AND before_term_id IS NULL AND corrects_event_id IS NOT NULL AND member_key ~ '^[a-z0-9_]{1,32}$' AND correction_group_id IS NOT NULL AND correction_group_id=approval_id)),UNIQUE(org_id,id,employee_id,approval_id,member_key,corrects_event_id,kind,effective_date));
CREATE TABLE compensation_terms_version(org_id TEXT NOT NULL,id TEXT NOT NULL,employee_id TEXT NOT NULL,event_id TEXT NOT NULL,approval_id TEXT NOT NULL,payload_id TEXT NOT NULL,effective_date DATE NOT NULL,version_no BIGINT NOT NULL CHECK(version_no>0),PRIMARY KEY(org_id,id),UNIQUE(org_id,id,employee_id),UNIQUE(org_id,id,employee_id,event_id),UNIQUE(org_id,employee_id,version_no),UNIQUE(org_id,event_id),UNIQUE(org_id,id,event_id,employee_id));
CREATE TABLE compensation_payload(org_id TEXT NOT NULL,id TEXT NOT NULL,employee_id TEXT NOT NULL,record_id TEXT NOT NULL,version_id TEXT NOT NULL,object_kind TEXT NOT NULL CHECK(object_kind IN('compensation_proposal','compensation_terms','compensation_decision')),purpose TEXT NOT NULL CHECK(purpose='financial'),schema_type TEXT NOT NULL CHECK(schema_type IN('compensation.proposal.v1','compensation.terms.v1','compensation.decision.v1')),schema_version BIGINT NOT NULL CHECK(schema_version=1),format_version BIGINT NOT NULL CHECK(format_version=1),algorithm TEXT NOT NULL CHECK(algorithm='A256GCM-RANDOMNONCE'),dek_id TEXT NOT NULL,kek_id TEXT NOT NULL CHECK(length(kek_id)>0),kek_version BIGINT NOT NULL CHECK(kek_version>0),wrapped_dek BYTEA NOT NULL CHECK(octet_length(wrapped_dek)>0),sealed_bytes BYTEA NOT NULL CHECK(octet_length(sealed_bytes)>=28),created_at TIMESTAMPTZ NOT NULL,proposal_id TEXT,proposal_revision_id TEXT,term_id TEXT,approval_id TEXT,PRIMARY KEY(org_id,id),UNIQUE(org_id,id,employee_id),UNIQUE(org_id,proposal_id,proposal_revision_id,employee_id,id),UNIQUE(org_id,term_id,employee_id,id),UNIQUE(org_id,approval_id,employee_id,id),CHECK((object_kind='compensation_proposal' AND schema_type='compensation.proposal.v1' AND proposal_id IS NOT NULL AND proposal_revision_id IS NOT NULL AND term_id IS NULL AND approval_id IS NULL AND record_id=proposal_id AND version_id=proposal_revision_id AND id=proposal_revision_id) OR (object_kind='compensation_terms' AND schema_type='compensation.terms.v1' AND term_id IS NOT NULL AND proposal_id IS NULL AND proposal_revision_id IS NULL AND approval_id IS NULL AND record_id=term_id AND version_id=term_id AND id=term_id) OR (object_kind='compensation_decision' AND schema_type='compensation.decision.v1' AND approval_id IS NOT NULL AND proposal_id IS NULL AND proposal_revision_id IS NULL AND term_id IS NULL AND record_id=approval_id AND version_id=approval_id AND id=approval_id)));
