CREATE TABLE compensation_correction_member(org_id TEXT NOT NULL,group_id TEXT NOT NULL,employee_id TEXT NOT NULL,member_key TEXT NOT NULL CHECK(member_key ~ '^[a-z0-9_]{1,32}$'),action TEXT NOT NULL CHECK(action IN('replace','reverse')),original_event_id TEXT NOT NULL,event_id TEXT NOT NULL,before_term_id TEXT,after_term_id TEXT,effective_date DATE NOT NULL,event_kind TEXT GENERATED ALWAYS AS (CASE action WHEN 'replace' THEN 'correction_replacement' ELSE 'correction_reversal' END) STORED,PRIMARY KEY(org_id,group_id,member_key),UNIQUE(org_id,group_id,original_event_id),UNIQUE(org_id,event_id),UNIQUE(org_id,group_id,employee_id,member_key,event_id),CHECK((action='replace' AND after_term_id IS NOT NULL) OR (action='reverse' AND before_term_id IS NULL)));
