CREATE TABLE compensation_command_receipt(org_id TEXT NOT NULL,subject_id TEXT NOT NULL,operation TEXT NOT NULL CHECK(operation IN('OP-COMP-03','OP-COMP-04','OP-COMP-05','OP-SEC-05')),key TEXT NOT NULL,digest BYTEA NOT NULL CHECK(octet_length(digest)=32),digest_key_version BIGINT NOT NULL CHECK(digest_key_version=1),result_json TEXT NOT NULL CHECK(jsonb_typeof(result_json::jsonb)='object' AND (NOT result_json::jsonb ? 'proposal' OR result_json::jsonb->'proposal'='null'::jsonb)),recorded_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(org_id,subject_id,operation,key));
