nt_id AND interview_id IS NULL AND note_head_id IS NULL AND note_version_id IS NULL AND action_item_id IS NULL AND compensation_proposal_id IS NULL AND compensation_term_id IS NULL) OR (object_kind='compensation_term' AND compensation_term_id IS NOT NULL AND object_ref=compensation_term_id AND interview_id IS NULL AND note_head_id IS NULL AND note_version_id IS NULL AND action_item_id IS NULL AND compensation_proposal_id IS NULL AND compensation_event_id IS NULL)))));
