ALTER TABLE access_grant ADD CONSTRAINT access_grant_object_family CHECK((object_kind IS NULL OR (purpose='interview_followup' AND ((capability IN('interview.read','interview.write') AND category='metadata' AND object_kind='interview') OR (capability='note.read' AND category IN('shared','manager_private','hr_confidential') AND object_kind IN('interview','note_head','note_version')) OR (capability IN('note.write','note.publish') AND category IN('shared','manager_private','hr_confidential') AND object_kind IN('interview','note_head')) OR (capability IN('action.read','action.write') AND category='shared' AND object_kind IN('interview','action_item')) OR (capability='sensitive.export' AND ((category='metadata' AND object_kind='interview') OR (category IN('shared','manager_private','hr_confidential') AND object_kind IN('interview','note_head','note_version')) OR (category='shared' AND object_kind='action_item'))))) OR (purpose='compensation_management' AND category='financial' AND ((capability IN('compensation.read','sensitive.export') AND object_kind IN('compensation_proposal','compensation_event','compensation_term')) OR (capability IN('compensation.propose','compensation.approve') AND object_kind='compensation_proposal')))));
ALTER TABLE access_grant ADD CONSTRAINT access_grant_financial_relation CHECK(category<>'financial' OR relation_bound=false);
ALTER TABLE access_grant ADD CONSTRAINT access_grant_financial_object_0 FOREIGN KEY(org_id,compensation_proposal_id,object_employee_id) REFERENCES compensation_proposal(org_id,id,employee_id);
ALTER TABLE access_grant ADD CONSTRAINT access_grant_financial_object_1 FOREIGN KEY(org_id,compensation_event_id,object_employee_id) REFERENCES compensation_event(org_id,id,employee_id);
ALTER TABLE access_grant ADD CONSTRAINT access_grant_financial_object_2 FOREIGN KEY(org_id,compensation_term_id,object_employee_id) REFERENCES compensation_terms_version(org_id,id,employee_id);
ALTER TABLE audit_event DROP CONSTRAINT audit_event_operation_check;
ALTER TABLE audit_event ADD CONSTRAINT audit_event_operation_check CHECK(operation IN('OP-ORG-01','OP-ORG-02','OP-ORG-03','OP-ORG-04','OP-ORG-05','OP-ORG-07','OP-ORG-06','OP-ORG-08','OP-SEC-01','OP-SEC-02','OP-SEC-03','OP-SEC-06','AUTH-LOGIN','AUTH-STEP-UP','AUTH-LOGOUT','AUTH-BIND','AUTH-UNBIND','OP-INT-01','OP-INT-02','OP-INT-03','OP-INT-04','OP-INT-05','OP-INT-06','OP-INT-07','OP-INT-08','OP-SEC-05','OP-COMP-01','OP-COMP-02','OP-COMP-03','OP-COMP-04','OP-COMP-05'));
ALTER TABLE audit_event DROP CONSTRAINT audit_event_purpose_check;
ALTER TABLE audit_event ADD CONSTRAINT audit_event_purpose_check CHECK(purpose IN('organization_management','security_administration','interview_followup','compensation_management',''));
CREATE FUNCTION compensation_grant_owner_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.compensation_proposal_id IS DISTINCT FROM OLD.compensation_proposal_id OR NEW.compensation_event_id IS DISTINCT FROM OLD.compensation_event_id OR NEW.compensation_term_id IS DISTINCT FROM OLD.compensation_term_id THEN RAISE EXCEPTION 'immutable compensation owner' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
CREATE TRIGGER compensation_grant_owner_immutable BEFORE UPDATE ON access_grant FOR EACH ROW EXECUTE FUNCTION compensation_grant_owner_immutable();
ALTER TABLE oidc_transaction DROP CONSTRAINT oidc_transaction_action_check;
ALTER TABLE oidc_transaction ADD CONSTRAINT oidc_transaction_action_check CHECK(action IN('','pii.write','access_grant.manage','note.publish','sensitive.export','compensation.read','compensation.propose','compensation.approve'));
ALTER TABLE oidc_transaction DROP CONSTRAINT oidc_transaction_check2;
ALTER TABLE oidc_transaction ADD CONSTRAINT oidc_transaction_check2 CHECK((mode='login' AND action='' AND expected_identity IS NULL) OR (mode='step_up' AND action IN('pii.write','access_grant.manage','note.publish','sensitive.export','compensation.read','compensation.propose','compensation.approve') AND previous_hash IS NOT NULL AND expected_identity IS NOT NULL));
