CREATE FUNCTION compensation_fact_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable compensation fact' USING ERRCODE='23514'; END $$;
CREATE TRIGGER compensation_proposal_revision_immutable BEFORE UPDATE OR DELETE ON compensation_proposal_revision FOR EACH ROW EXECUTE FUNCTION compensation_fact_immutable();
CREATE TRIGGER compensation_approval_immutable BEFORE UPDATE OR DELETE ON compensation_approval FOR EACH ROW EXECUTE FUNCTION compensation_fact_immutable();
CREATE TRIGGER compensation_event_immutable BEFORE UPDATE OR DELETE ON compensation_event FOR EACH ROW EXECUTE FUNCTION compensation_fact_immutable();
CREATE TRIGGER compensation_terms_version_immutable BEFORE UPDATE OR DELETE ON compensation_terms_version FOR EACH ROW EXECUTE FUNCTION compensation_fact_immutable();
CREATE TRIGGER compensation_payload_immutable BEFORE UPDATE OR DELETE ON compensation_payload FOR EACH ROW EXECUTE FUNCTION compensation_fact_immutable();
CREATE TRIGGER compensation_correction_group_immutable BEFORE UPDATE OR DELETE ON compensation_correction_group FOR EACH ROW EXECUTE FUNCTION compensation_fact_immutable();
CREATE TRIGGER compensation_correction_member_immutable BEFORE UPDATE OR DELETE ON compensation_correction_member FOR EACH ROW EXECUTE FUNCTION compensation_fact_immutable();
CREATE TRIGGER compensation_command_receipt_immutable BEFORE UPDATE OR DELETE ON compensation_command_receipt FOR EACH ROW EXECUTE FUNCTION compensation_fact_immutable();
CREATE FUNCTION compensation_proposal_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'immutable compensation owner' USING ERRCODE='23514'; END IF; IF NEW.org_id IS DISTINCT FROM OLD.org_id OR NEW.id IS DISTINCT FROM OLD.id OR NEW.employee_id IS DISTINCT FROM OLD.employee_id OR NEW.author_subject_id IS DISTINCT FROM OLD.author_subject_id OR NEW.recorded_at IS DISTINCT FROM OLD.recorded_at THEN RAISE EXCEPTION 'immutable compensation owner' USING ERRCODE='23514'; END IF; IF NEW.revision<>OLD.revision+1 OR NOT ((OLD.status='draft' AND NEW.status IN('draft','submitted','withdrawn')) OR (OLD.status='submitted' AND NEW.status IN('approved','rejected','withdrawn'))) OR (OLD.status='submitted' AND (NEW.kind IS DISTINCT FROM OLD.kind OR NEW.effective_date IS DISTINCT FROM OLD.effective_date OR NEW.before_term_id IS DISTINCT FROM OLD.before_term_id OR NEW.basis_revision IS DISTINCT FROM OLD.basis_revision)) THEN RAISE EXCEPTION 'invalid compensation transition' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
CREATE TRIGGER compensation_proposal_guard BEFORE UPDATE OR DELETE ON compensation_proposal FOR EACH ROW EXECUTE FUNCTION compensation_proposal_guard();
CREATE FUNCTION compensation_aggregate_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'immutable compensation owner' USING ERRCODE='23514'; END IF; IF NEW.org_id IS DISTINCT FROM OLD.org_id OR NEW.employee_id IS DISTINCT FROM OLD.employee_id OR NEW.revision NOT IN(OLD.revision,OLD.revision+1) THEN RAISE EXCEPTION 'invalid compensation aggregate' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
CREATE TRIGGER compensation_aggregate_guard BEFORE UPDATE OR DELETE ON compensation_aggregate FOR EACH ROW EXECUTE FUNCTION compensation_aggregate_guard();
